const inputItems = $input.all();

let sheetRows = [];
if (inputItems.length === 1 && Array.isArray(inputItems[0].json.rows)) {
  sheetRows = inputItems[0].json.rows;
} else {
  sheetRows = inputItems.map(i => i.json);
}

function pad(n){ return n < 10 ? '0' + n : '' + n; }

// Force Europe/London timezone (handles GMT & BST automatically)
const now = new Date();
const londonDateStr = now.toLocaleString('en-US', { timeZone: 'Europe/London' });
const londonDate = new Date(londonDateStr);

const hours = pad(londonDate.getHours());
const minutes = pad(londonDate.getMinutes());
const currentHHMM = `${hours}:${minutes}`;

const dayNames = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const currentDayName = dayNames[londonDate.getDay()];

function normalizeTime(t) {
  if (t === null || t === undefined) return null;
  if (typeof t === 'object' && t instanceof Date) {
    return `${pad(t.getHours())}:${pad(t.getMinutes())}`;
  }
  const s = String(t).trim();
  const m = s.match(/(\d{1,2}):(\d{2})/);
  if (!m) return s;
  return `${pad(Number(m[1]))}:${m[2]}`;
}

const matched = sheetRows.filter(r => {
  const day = (r.Day || r.day || '').toString().trim();
  const sendTimeRaw = r.SendTime || r.sendTime || r['SendTime'] || r['sendtime'];
  const sendTime = normalizeTime(sendTimeRaw);
  return day.toLowerCase() === currentDayName.toLowerCase() && sendTime === currentHHMM;
});

if (matched.length === 0) {
  return [{ json: { matched: false, message: `No confession for ${currentDayName} at ${currentHHMM}` } }];
}

const out = matched.map(row => {
  const title = row.Title || row.title || '';
  const scriptures = row.Scriptures || row.scriptures || '';
  const confession = row.Confession || row.confession || '';
  const email = row.Email || row.email || null;
  const type = row.Type || row.type || null;
  const body = `${title}\n\n${confession}\n\nScripture: ${scriptures}`;
  return {
    json: {
      matched: true,
      day: currentDayName,
      sendTime: currentHHMM,
      title,
      scriptures,
      confession,
      body,
      email,
      type,
      rawRow: row
    }
  };
});

return out;
